<script setup lang="ts">import{onMounted,ref}from'vue';import{NButton,NTag,useMessage}from'naive-ui';import{api}from'../api';const rows=ref<any[]>([]),message=useMessage(),uploading=ref(false);async function load(){rows.value=await api.get('/themes') as any[]}async function activate(id:string){try{await api.post(`/themes/${id}/activate`);message.success('主题已启用');load()}catch(e:any){message.error(e.message)}}async function upload(ev:Event){const file=(ev.target as HTMLInputElement).files?.[0];if(!file)return;uploading.value=true;try{const data=new FormData();data.append('file',file);await api.post('/themes/upload',data);message.success('主题安装成功');load()}catch(e:any){message.error(e.message)}finally{uploading.value=false;(ev.target as HTMLInputElement).value=''}}</script>
<template><div class="page-head"><div><h1>主题外观</h1><span style="color:#8b93a1">安装前会检查路径穿越、文件类型、条目数与解压大小</span></div><label class="upload-btn"><input type="file" accept=".zip" hidden @change="upload"><span>{{uploading?'安装中…':'上传主题 ZIP'}}</span></label></div><div class="metric-grid"><article v-for="t in rows" :key="t.id" class="metric"><div><n-tag v-if="t.builtin">内置</n-tag> <n-tag v-if="t.active" type="success">当前主题</n-tag></div><strong style="font-size:22px">{{t.name}}</strong><span>v{{t.version}} · {{t.author}}</span><p>{{t.description}}</p><n-button v-if="!t.active" type="primary" size="small" @click="activate(t.id)">启用</n-button></article></div></template>
<style scoped>.upload-btn{display:inline-flex;padding:9px 16px;border-radius:8px;background:#18a058;color:white;cursor:pointer;font-weight:600}</style>
